1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"sort"
8		"unicode/utf8"
9	)
10	
11	// PlanChange is one record in a lineage adjustment plan: the dataset name and
12	// the complete list of its direct upstreams after the batch is applied.
13	//
14	// A change may name a dataset that does not exist yet (it is registered) or an
15	// existing dataset (its direct upstreams are replaced wholesale). Datasets not
16	// mentioned in the plan keep their current direct upstreams.
17	type PlanChange struct {
18		Name      string   `json:"name"`
19		Upstreams []string `json:"upstreams"`
20	}
21	
22	// Plan is a batch of lineage adjustments read from a JSON file.
23	//
24	// Removals names datasets that must be absent from the final graph. Deleting a
25	// name that does not currently exist is a no-op (it is not reported as an
26	// actual removal), so a successful plan can be applied again with empty change
27	// and impact lists. A name listed in Removals must not also appear in Changes.
28	type Plan struct {
29		Changes  []PlanChange `json:"changes"`
30		Removals []string     `json:"removals"`
31	}
32	
33	// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
34	// downstream dataset derives from the upstream dataset.
35	type Relation struct {
36		Upstream   string `json:"upstream"`
37		Downstream string `json:"downstream"`
38	}
39	
40	// GraphDataset is one dataset record in the on-disk graph JSON.
41	type GraphDataset struct {
42		Name      string   `json:"name"`
43		Upstreams []string `json:"upstreams"`
44	}
45	
46	// GraphFile is the on-disk JSON representation of a lineage graph.
47	type GraphFile struct {
48		Datasets []GraphDataset `json:"datasets"`
49	}
50	
51	// BatchReport is the deterministic report produced by preview and apply.
52	//
53	// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
54	// lists are sorted by name byte order; relation lists are sorted by upstream
55	// then downstream.
56	type BatchReport struct {
57		FinalGraph          GraphFile  `json:"finalGraph"`
58		NewDatasets         []string   `json:"newDatasets"`
59		ChangedDatasets     []string   `json:"changedDatasets"`
60		RemovedDatasets     []string   `json:"removedDatasets"`
61		AddedRelations      []Relation `json:"addedRelations"`
62		RemovedRelations    []Relation `json:"removedRelations"`
63		AffectedDownstreams []string   `json:"affectedDownstreams"`
64	}
65	
66	// validatedGraphAdjacency is the single authority for whether an existing
67	// in-memory graph is legal, shared by the public ValidateGraph check and every
68	// operation that only reads an existing graph — preview and apply, graph
69	// export, and snapshot builds. It runs every structure rule once and returns
70	// the graph's canonical parent adjacency (sorted, duplicate-free):
71	//
72	//   - a nil map is ErrNotInitialized;
73	//   - dataset names and direct upstream references must be valid UTF-8 (the
74	//     encoding gate runs before anything quotes the names, so an unusable
75	//     upstream is never misreported as a missing one and its original bytes
76	//     stay readable in the error);
77	//   - nil lineage nodes and empty dataset names are rejected;
78	//   - every direct upstream must be a registered dataset, with the referrer
79	//     and the referenced name both in the error;
80	//   - the parent edges must be acyclic (self-dependency included), with the
81	//     datasets on the cycle named.
82	//
83	// The whole check is read-only: it builds fresh slices from each node's
84	// stored Parents and never touches the caller's nodes or their parent and
85	// child lists, including their order and duplicates. Whether the graph is
86	// legal depends solely on the dataset names and the direct-upstream
87	// relations: an initialized but empty graph is legal.
88	func validatedGraphAdjacency(graph map[string]*Lineage) (adjacency, error) {
89		if graph == nil {
90			return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
91		}
92		if err := validateInMemoryNamesUTF8(graph); err != nil {
93			return nil, err
94		}
95		records := make([]GraphDataset, 0, len(graph))
96		for name, entry := range graph {
97			if entry == nil {
98				return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
99			}
100			if name == "" {
101				return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
102			}
103			records = append(records, GraphDataset{Name: name, Upstreams: entry.Parents})
104		}
105		adj, err := normalizeDatasets(records)
106		if err != nil {
107			return nil, err
108		}
109		return validateGraphAdjacency(adj)
110	}
111	
112	// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
113	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
114	// references), missing upstreams, and cycles. It does not mutate the graph.
115	//
116	// A graph that fails validation cannot be used as the basis for a batch: an
117	// adjustment plan must not be allowed to paper over pre-existing corruption.
118	// This is the same judgment preview, apply, graph export, and snapshot builds
119	// make on the original graph (see validatedGraphAdjacency).
120	func ValidateGraph(graph map[string]*Lineage) error {
121		_, err := validatedGraphAdjacency(graph)
122		return err
123	}
124	
125	// validatePlanNamesUTF8 rejects a plan in which any name that takes part in
126	// the adjustment — a change record's name, one of its direct upstream names,
127	// or a removals entry — is not valid UTF-8. It is the in-memory counterpart
128	// of the raw-literal scan the plan reader runs (checkPlanNameEncoding): a
129	// Plan built directly in Go never passed through that reader, so without
130	// this gate PreviewBatch and ApplyBatch could register datasets the graph
131	// exporter must refuse and produce reports whose JSON silently rewrites the
132	// bad bytes to U+FFFD (two distinct corrupted names would then print as one).
133	//
134	// Plan order is checked as given: the name of record i comes before its
135	// upstreams, and removals follow all changes, so the first reported position
136	// is the earliest offending name the caller submitted. The error names the
137	// field ("name", "upstreams", or "removals"), the zero-based record or array
138	// position, and — for an upstream — its zero-based position inside that
139	// record. The offending name is quoted with %q, which renders the original
140	// bytes as \x escapes rather than replacing them with U+FFFD, so "p\xff" and
141	// "p\xfe" stay distinguishable. The plan is only read, never normalized or
142	// mutated. Register keeps accepting raw Go strings; this gate belongs only
143	// to the batch boundary, where an unusable name would enter a graph and a
144	// report that are promised exportable.
145	func validatePlanNamesUTF8(plan Plan) error {
146		for i, change := range plan.Changes {
147			if !utf8.ValidString(change.Name) {
148				return fmt.Errorf("%w: field %q in the change record at index %d of %q contains invalid UTF-8 bytes: %q",
149					ErrInvalidArgument, "name", i, "changes", change.Name)
150			}
151			for j, upstream := range change.Upstreams {
152				if !utf8.ValidString(upstream) {
153					// Report the unusable name itself, never a missing-upstream
154					// error: the encoding defect takes precedence over whether
155					// the referenced dataset exists in the final graph.
156					return fmt.Errorf("%w: field %q at index %d in the change record at index %d of %q contains invalid UTF-8 bytes: %q",
157						ErrInvalidArgument, "upstreams", j, i, "changes", upstream)
158				}
159			}
160		}
161		for i, name := range plan.Removals {
162			if !utf8.ValidString(name) {
163				return fmt.Errorf("%w: field %q at index %d contains invalid UTF-8 bytes: %q",
164					ErrInvalidArgument, "removals", i, name)
165			}
166		}
167		return nil
168	}
169	
170	// computeBatch validates the graph and plan, then computes the final adjacency
171	// and the diff report. It does not mutate graph. The returned adjacency is the
172	// graph as it will be after the batch; callers that want to commit it should
173	// pass it to applyAdjacency.
174	func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
175		// One read of the existing graph settles both its legality and its
176		// canonical relations: the original graph must be legal even when the
177		// plan deletes a bad node or clears a dangling upstream, and the returned
178		// normalized adjacency is the basis the final graph is computed from.
179		original, err := validatedGraphAdjacency(graph)
180		if err != nil {
181			return nil, nil, err
182		}
183	
184		// Check every name the plan carries before anything that would quote it,
185		// hash it, or turn the report into JSON: the file reader already rejects
186		// these at the raw-literal level, but a plan constructed directly through
187		// the Go API bypasses that reader, and without this gate it could register
188		// a dataset whose name cannot be exported — two names differing only in an
189		// invalid byte ("p\xff" vs "p\xfe") would even render identically once the
190		// report is marshaled. This is the in-memory counterpart of the raw scan;
191		// see name_encoding.go.
192		if err := validatePlanNamesUTF8(plan); err != nil {
193			return nil, nil, err
194		}
195	
196		// Validate the plan: empty names and duplicate declarations reject the
197		// whole batch, naming the dataset and the reason.
198		declarations := make(map[string]int, len(plan.Changes))
199		for _, change := range plan.Changes {
200			if change.Name == "" {
201				return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
202			}
203			declarations[change.Name]++
204			if declarations[change.Name] > 1 {
205				return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
206			}
207		}
208	
209		// Validate removals: empty names, duplicate names, and names also declared
210		// as changes all reject the whole batch with the name and reason.
211		removalDecls := make(map[string]int, len(plan.Removals))
212		for _, name := range plan.Removals {
213			if name == "" {
214				return nil, nil, fmt.Errorf("%w: plan removals contain a dataset with an empty name", ErrInvalidArgument)
215			}
216			removalDecls[name]++
217			if removalDecls[name] > 1 {
218				return nil, nil, fmt.Errorf("%w: dataset %q is listed %d times in removals", ErrInvalidArgument, name, removalDecls[name])
219			}
220			if _, ok := declarations[name]; ok {
221				return nil, nil, fmt.Errorf("%w: dataset %q appears in both changes and removals", ErrInvalidArgument, name)
222			}
223		}
224	
225		// Build the final adjacency: start from the original parents, replace each
226		// planned dataset's parents with its normalized upstreams. Being named in
227		// the plan does not by itself make a dataset new or changed — that is
228		// judged below by diffing the original and final graphs, exactly the way a
229		// snapshot comparison judges two versions.
230		final := make(adjacency, len(original)+len(plan.Changes))
231		for name, parents := range original {
232			final[name] = append([]string(nil), parents...)
233		}
234		for name := range removalDecls {
235			delete(final, name)
236		}
237		for _, change := range plan.Changes {
238			final[change.Name] = uniqueSorted(change.Upstreams)
239		}
240	
241		// Every upstream must resolve to a dataset that exists in the FINAL graph
242		// (new datasets may reference each other regardless of plan order; a
243		// retained dataset that still references a deleted name is rejected here,
244		// with both the referrer and the referenced name in the error). Iterate
245		// over sorted names so the reported pair is deterministic.
246		names := make([]string, 0, len(final))
247		for name := range final {
248			names = append(names, name)
249		}
250		sort.Strings(names)
251		for _, name := range names {
252			for _, parent := range final[name] {
253				if _, ok := final[parent]; !ok {
254					return nil, nil, fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the final graph", ErrNotFound, name, parent)
255				}
256			}
257		}
258		// The final graph must be acyclic, judged after all replacements.
259		if err := validateAcyclic(final); err != nil {
260			return nil, nil, err
261		}
262	
263		// Classify the dataset-level changes with the shared old -> new rule a
264		// snapshot comparison uses (see diffDatasets): only-in-final is new,
265		// only-in-original is removed, present-on-both is changed only when the
266		// direct upstream set actually differs. Deleting a name that does not
267		// exist is a no-op and is not reported, so a successful plan can be
268		// applied again with empty change and impact lists.
269		newNames, removedNames, changedNames := diffDatasets(original, final)
270	
271		added, removed := diffRelations(original, final)
272		affected := affectedDownstreams(original, final, newNames, changedNames, removedNames)
273	
274		report := &BatchReport{
275			FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
276			NewDatasets:         newNames,
277			ChangedDatasets:     changedNames,
278			RemovedDatasets:     removedNames,
279			AddedRelations:      added,
280			RemovedRelations:    removed,
281			AffectedDownstreams: affected,
282		}
283		// Guarantee non-nil slices so JSON encodes empty lists as [].
284		if report.NewDatasets == nil {
285			report.NewDatasets = []string{}
286		}
287		if report.ChangedDatasets == nil {
288			report.ChangedDatasets = []string{}
289		}
290		if report.RemovedDatasets == nil {
291			report.RemovedDatasets = []string{}
292		}
293		if report.AddedRelations == nil {
294			report.AddedRelations = []Relation{}
295		}
296		if report.RemovedRelations == nil {
297			report.RemovedRelations = []Relation{}
298		}
299		if report.AffectedDownstreams == nil {
300			report.AffectedDownstreams = []string{}
301		}
302		return report, final, nil
303	}
304	
305	// PreviewBatch validates the graph and plan and returns the report WITHOUT
306	// mutating graph. Preview and apply for the same graph and plan produce
307	// identical reports.
308	//
309	// As well as the structural plan rules (empty names, duplicate declarations,
310	// unresolvable upstreams, cycles), every name the plan carries — a change
311	// record's name, any of its direct upstreams, and every removals entry — must
312	// be valid UTF-8 even when the plan was constructed directly in Go instead of
313	// read by UnmarshalPlan. A name that is not valid UTF-8 rejects the whole
314	// batch with ErrInvalidArgument before any dataset could be registered or any
315	// report produced, so a success report can always be marshaled to JSON and an
316	// applied graph can always be exported. See validatePlanNamesUTF8.
317	func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
318		report, _, err := computeBatch(graph, plan)
319		return report, err
320	}
321	
322	// ApplyBatch validates the plan, applies it to graph, and returns the report.
323	// On rejection — including a plan that names a dataset, upstream, or removal
324	// with bytes that are not valid UTF-8 — graph is left completely unchanged.
325	func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
326		report, final, err := computeBatch(graph, plan)
327		if err != nil {
328			return nil, err
329		}
330		applyAdjacency(graph, final)
331		return report, nil
332	}
333	
334	// applyAdjacency rewrites the in-memory graph to match the final adjacency. It
335	// is the apply path of the shared relationship rule in materializeLineage, the
336	// same rule a graph reader follows: nodes absent from final are removed,
337	// parents are replaced wholesale with independent copies, and children are
338	// rebuilt from the parent edges. Surviving *Lineage records are updated in
339	// place, so node pointers a Go caller already holds expose the new
340	// relationships after the batch returns.
341	func applyAdjacency(graph map[string]*Lineage, final adjacency) {
342		materializeLineage(graph, final)
343	}
344	
345	// diffDatasets is the single authority for classifying dataset-level changes
346	// between two versions of a graph, shared by the batch report (preview and
347	// apply) and the snapshot comparison so both can never disagree about the
348	// rule. Changes are always judged in the direction original -> final:
349	//
350	//   - a dataset present only in final is NEW — even when it arrives carrying
351	//     upstreams, it is never also listed as changed;
352	//   - a dataset present only in original is REMOVED — a removed dataset is
353	//     never also listed as an upstream change;
354	//   - a dataset present on both sides is CHANGED only when its direct
355	//     upstream set actually differs; a dataset whose upstreams were cleared
356	//     still exists (as a root), so it is changed, not removed.
357	//
358	// Names are case-sensitive and compared verbatim; only the name set and each
359	// dataset's normalized upstream set matter, never record order, upstream
360	// order, or duplicate upstreams. Each returned list is sorted by name byte
361	// order and is nil when empty; callers normalize nil to [] for JSON.
362	func diffDatasets(original, final adjacency) (newNames, removedNames, changedNames []string) {
363		for name, finalParents := range final {
364			if originalParents, ok := original[name]; !ok {
365				newNames = append(newNames, name)
366			} else if !stringSliceEqual(originalParents, finalParents) {
367				changedNames = append(changedNames, name)
368			}
369		}
370		for name := range original {
371			if _, ok := final[name]; !ok {
372				removedNames = append(removedNames, name)
373			}
374		}
375		sort.Strings(newNames)
376		sort.Strings(removedNames)
377		sort.Strings(changedNames)
378		return newNames, removedNames, changedNames
379	}
380	
381	// diffRelations returns the directed edges present in final but not original
382	// (added) and present in original but not final (removed). Both lists are
383	// sorted by upstream then downstream.
384	func diffRelations(original, final adjacency) (added, removed []Relation) {
385		origEdges := edgeSet(original)
386		finalEdges := edgeSet(final)
387		for e := range finalEdges {
388			if !origEdges[e] {
389				added = append(added, e)
390			}
391		}
392		for e := range origEdges {
393			if !finalEdges[e] {
394				removed = append(removed, e)
395			}
396		}
397		sortRelations(added)
398		sortRelations(removed)
399		return added, removed
400	}
401	
402	// edgeSet collapses the adjacency into a set of upstream->downstream edges.
403	func edgeSet(adj adjacency) map[Relation]bool {
404		set := make(map[Relation]bool)
405		for downstream, parents := range adj {
406			for _, upstream := range parents {
407				set[Relation{Upstream: upstream, Downstream: downstream}] = true
408			}
409		}
410		return set
411	}
412	
413	// sortRelations sorts by upstream then downstream.
414	func sortRelations(rels []Relation) {
415		sort.Slice(rels, func(i, j int) bool {
416			if rels[i].Upstream != rels[j].Upstream {
417				return rels[i].Upstream < rels[j].Upstream
418			}
419			return rels[i].Downstream < rels[j].Downstream
420		})
421	}
422	
423	// affectedDownstreams computes the impact set: starting from the seed datasets
424	// (new, actually changed, or actually removed), follow downstream (children)
425	// edges in BOTH the original and the final graphs. Datasets that are
426	// themselves seeds are excluded from the output; every other reachable dataset
427	// is included once.
428	//
429	// Walking both graphs matters when relations are deleted: a dataset that was
430	// reachable downstream before the change (and thus loses a lineage path) is
431	// still affected even if the edge is gone in the final graph. Removed datasets
432	// are seeds too, so a downstream that lost its upstream node is counted.
433	func affectedDownstreams(original, final adjacency, newNames, changedNames, removedNames []string) []string {
434		seeds := make(map[string]bool, len(newNames)+len(changedNames)+len(removedNames))
435		for _, name := range newNames {
436			seeds[name] = true
437		}
438		for _, name := range changedNames {
439			seeds[name] = true
440		}
441		for _, name := range removedNames {
442			seeds[name] = true
443		}
444	
445		origChildren := invertAdjacency(original)
446		finalChildren := invertAdjacency(final)
447	
448		seen := make(map[string]bool)
449		queue := make([]string, 0, len(seeds))
450		for seed := range seeds {
451			queue = append(queue, seed)
452		}
453		for len(queue) > 0 {
454			node := queue[0]
455			queue = queue[1:]
456			for _, child := range origChildren[node] {
457				if !seen[child] {
458					seen[child] = true
459					queue = append(queue, child)
460				}
461			}
462			for _, child := range finalChildren[node] {
463				if !seen[child] {
464					seen[child] = true
465					queue = append(queue, child)
466				}
467			}
468		}
469	
470		out := make([]string, 0, len(seen))
471		for name := range seen {
472			if !seeds[name] {
473				out = append(out, name)
474			}
475		}
476		sort.Strings(out)
477		return out
478	}
479	
480	// invertAdjacency maps each dataset to the datasets that depend on it (its
481	// children), with each child list sorted by name.
482	func invertAdjacency(adj adjacency) map[string][]string {
483		children := make(map[string][]string, len(adj))
484		for name, parents := range adj {
485			for _, parent := range parents {
486				children[parent] = append(children[parent], name)
487			}
488		}
489		for name := range children {
490			sort.Strings(children[name])
491		}
492		return children
493	}
494	
495	// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
496	// records with non-nil upstream lists.
497	func adjacencyToDatasets(adj adjacency) []GraphDataset {
498		names := make([]string, 0, len(adj))
499		for name := range adj {
500			names = append(names, name)
501		}
502		sort.Strings(names)
503		ds := make([]GraphDataset, 0, len(names))
504		for _, name := range names {
505			parents := adj[name]
506			if parents == nil {
507				parents = []string{}
508			}
509			ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
510		}
511		return ds
512	}
513	
514	// stringSliceEqual reports whether a and b contain the same strings in the
515	// same order. Both are expected to be sorted and duplicate-free.
516	func stringSliceEqual(a, b []string) bool {
517		if len(a) != len(b) {
518			return false
519		}
520		for i := range a {
521			if a[i] != b[i] {
522				return false
523			}
524		}
525		return true
526	}
527	
528	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
529	// The graph must satisfy every structure rule a reader enforces; nil nodes,
530	// empty names, names that are not valid UTF-8 (dataset names or direct upstream
531	// references), missing upstreams, and dependency cycles (including a dataset
532	// that lists itself) reject the export with no bytes returned, so a successful
533	// result can always be read back with UnmarshalGraphFile. The check is
534	// read-only: the in-memory graph is never modified.
535	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
536		adj, err := validatedGraphAdjacency(graph)
537		if err != nil {
538			return nil, err
539		}
540		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
541		return json.MarshalIndent(gf, "", "  ")
542	}
543	
544	// UnmarshalGraphFile parses the on-disk graph JSON and rebuilds the in-memory
545	// graph (parents and derived children). The graph is checked with the same
546	// structural rules a snapshot enforces (empty names, duplicate datasets,
547	// missing upstreams, and cycles); a structurally invalid graph is rejected so
548	// it cannot be used as the basis for a batch. As in a snapshot, a known field
549	// declared twice within the same object — datasets in the graph object, name
550	// or upstreams in a dataset record — is ambiguous and rejects the whole file,
551	// even when the duplicates carry identical values.
552	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
553		if err := checkGraphFileDuplicateFields(data); err != nil {
554			return nil, err
555		}
556		// Every name the graph carries must survive decoding exactly as written:
557		// a raw literal with invalid UTF-8 bytes or an unpaired surrogate escape
558		// would be silently rewritten to U+FFFD by json.Unmarshal, and a corrupted
559		// upstream could then resolve to a genuinely different dataset (an edge
560		// written as "源" plus a lone \uD800 would point at the real dataset
561		// "源�"). See name_encoding.go.
562		if err := checkGraphNameEncoding(data); err != nil {
563			return nil, err
564		}
565		var gf GraphFile
566		if err := json.Unmarshal(data, &gf); err != nil {
567			return nil, fmt.Errorf("invalid graph JSON: %w", err)
568		}
569		adj, err := validateGraphStructureFromFile(gf.Datasets)
570		if err != nil {
571			return nil, err
572		}
573		// Rebuild children from the parent edges so the in-memory graph is
574		// consistent regardless of how the file was produced.
575		return lineageFromAdjacency(adj), nil
576	}
577	
578	// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
579	// duplicate declarations) is validated later by computeBatch so that preview
580	// and apply share identical rejection behavior.
581	//
582	// A known field declared twice within the same object — changes or removals
583	// at the top level, name or upstreams inside one change record — is
584	// ambiguous: the reader would silently keep only the last declaration and
585	// drop the earlier adjustment. The whole plan is refused instead, even when
586	// the duplicates carry identical values, one is null, or the surviving value
587	// is a legal empty list. Field names are recognized the same way the decoder
588	// resolves them (after JSON unescaping, with Unicode case folding), so a
589	// second declaration spelled "Changes" or "changes" still collides;
590	// dataset names themselves stay case-sensitive. Unknown fields keep their
591	// ignore-everything behavior and may repeat freely.
592	//
593	// Every name that takes part in the adjustment — each change record's name,
594	// every upstreams entry, and every removals entry — must also survive
595	// decoding exactly as written: a raw string literal carrying bytes that are
596	// not valid UTF-8, or a \u escape forming an unpaired surrogate, would be
597	// silently rewritten to U+FFFD by the decoder, and the corrupted name could
598	// then collide with a genuinely different dataset (a removals entry meant
599	// for no one could delete the dataset really named "�"). The whole plan is
600	// refused instead, naming the field and the zero-based record or array
601	// position, even when the corrupted name would only have matched a dataset
602	// that does not exist. A genuine "�", correctly paired surrogate escapes,
603	// and names that merely look like escapes (a backslash before an ordinary
604	// letter) stay legal; unknown fields and their nested strings are not
605	// checked. The raw scan is shared with the graph readers and lives in
606	// name_encoding.go; this file only supplies the plan document scope.
607	func UnmarshalPlan(data []byte) (Plan, error) {
608		var p Plan
609		if err := checkPlanDuplicateFields(data); err != nil {
610			return p, err
611		}
612		if err := json.Unmarshal(data, &p); err != nil {
613			return p, fmt.Errorf("invalid plan JSON: %w", err)
614		}
615		if err := checkPlanNameEncoding(data); err != nil {
616			return Plan{}, err
617		}
618		return p, nil
619	}
620	
621	// checkGraphFileDuplicateFields applies the shared repeated-known-field rule
622	// (see duplicate_fields.go) to a standalone graph file, supplying the graph
623	// file's own location: datasets may be declared only once in the top-level
624	// graph object, and name and upstreams only once in each dataset record. The
625	// scan is the same checkGraphObject ParseSnapshot runs on the embedded graph,
626	// so preview, apply, and snapshot can never disagree about a graph that
627	// repeats a known field.
628	func checkGraphFileDuplicateFields(data []byte) error {
629		return runFieldScan(data, func(dec *json.Decoder) error {
630			return checkGraphObject(dec, "at the top level of the graph")
631		})
632	}
633	
634	// checkPlanDuplicateFields applies the shared repeated-known-field rule (see
635	// duplicate_fields.go) to a plan, supplying the plan's own field scope and
636	// locations: changes or removals at the top level, and name or upstreams
637	// inside each change record. A change record carries the same fields as a
638	// dataset record, so both use the shared datasetRecordFields scope and a plan
639	// can never be judged differently from the other documents about what counts
640	// as a repeated field.
641	func checkPlanDuplicateFields(data []byte) error {
642		return runFieldScan(data, func(dec *json.Decoder) error {
643			return checkObjectFields(dec, "at the top level of the plan", []knownField{
644				{name: "changes", nested: func(dec *json.Decoder) error {
645					return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
646						return checkObjectFields(dec, fmt.Sprintf("in the change record at index %d of \"changes\"", index), datasetRecordFields)
647					})
648				}},
649				{name: "removals"},
650			})
651		})
652	}
653

