		}
	})

	t.Run("missing final upstream", func(t *testing.T) {
		graph := buildGraph(t, P("A"))
		plan := planOf(change("A", "ghost"))
		_, err := PreviewBatch(graph, plan)
		if !errors.Is(err, ErrNotFound) {
